import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Spinner } from 'react-bootstrap';

const MyEvents = () => {
  const [myEvents, setMyEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchMyEvents = async () => {
      try {
        const token = localStorage.getItem('authToken');
        if (!token) {
          setError('User not authenticated');
          return;
        }

        const response = await axios.get('http://localhost:8000/api/events/myevents', {
          headers: { Authorization: `Bearer ${token}` },
        });

        setMyEvents(response.data);
      } catch (error) {
        console.error('❌ Error fetching my events:', error.response?.data || error.message);
        setError('Failed to fetch registered events');
      } finally {
        setLoading(false);
      }
    };

    fetchMyEvents();
  }, []);

  return (
    <Container className="mt-5">
      <h2 className="text-center mb-4">My Registered Events</h2>

      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : error ? (
        <p className="text-danger text-center">{error}</p>
      ) : myEvents.length > 0 ? (
        <Row>
          {myEvents.map((event) => (
            <Col key={event._id} md={4} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>{event.title}</Card.Title>
                  <Card.Text>{event.description}</Card.Text>
                  <Card.Text>📅 {new Date(event.date).toLocaleDateString()}</Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <p className="text-center">No registered events yet.</p>
      )}
    </Container>
  );
};

export default MyEvents;
